/**
 * Константы, подставляемые сборкой.
 *
 * `__LEGAL_PAGES_READY__` объявляет плагин `plugins/legal-pages.ts` по итогу
 * `build-legal.mjs --check`: true — правовые страницы будут собраны в этот же
 * `dist/`, false — реквизитов не хватает и страниц не будет. Подвал вешает на
 * неё ссылки, поэтому ссылка на несуществующую страницу не попадает в бандл
 * вовсе, а не прячется условием во время работы.
 */
declare const __LEGAL_PAGES_READY__: boolean;
